import { appendFile, mkdir } from "node:fs/promises";
import { dirname, isAbsolute, join, relative, resolve } from "node:path";
import { pathToFileURL } from "node:url";

// Adapt authentication, declared hosts and schema validation to the official API.
// Retry only safe reads here; reconcile submitted writes from receipts first.
export async function requestJson(url, { headers = {}, signal } = {}) {
  for (let attempt = 0; attempt < 3; attempt++) {
    const response = await fetch(url, {
      headers,
      redirect: "error",
      signal: signal
        ? AbortSignal.any([signal, AbortSignal.timeout(30000)])
        : AbortSignal.timeout(30000),
    });
    if (response.status === 401 || response.status === 403)
      throw Object.assign(new Error("Credential rejected"), { exitCode: 77 });
    if (response.status === 429 || response.status >= 500) {
      if (attempt === 2)
        throw Object.assign(new Error("Service temporarily unavailable"), { exitCode: 75 });
      const retry = response.headers.get("retry-after");
      const seconds =
        retry && /^\d+$/.test(retry)
          ? Number(retry)
          : retry
            ? (Date.parse(retry) - Date.now()) / 1000
            : 2 ** attempt;
      if (!Number.isFinite(seconds) || seconds > 60)
        throw Object.assign(new Error("Retry later as directed by the service"), { exitCode: 75 });
      await new Promise((done) => setTimeout(done, Math.max(0, seconds) * 1000));
      continue;
    }
    if (!response.ok)
      throw Object.assign(new Error(`Unexpected HTTP status ${response.status}`), { exitCode: 76 });
    return response.json().catch(() => {
      throw Object.assign(new Error("Unexpected response format"), { exitCode: 76 });
    });
  }
}

export function outputPath(value) {
  const output = resolve(value);
  const distance = relative(process.cwd(), output);
  if (
    !distance ||
    distance === ".." ||
    distance.startsWith(`..${process.platform === "win32" ? "\\" : "/"}`) ||
    isAbsolute(distance)
  )
    throw Object.assign(new Error("Choose an output file inside the project"), { exitCode: 64 });
  return output;
}

export async function receipt({ requestId, jobId, status, estimatedCost, output }) {
  const file = join(process.cwd(), "connectors", process.env.VOYAGER_CONNECTOR, "receipts.jsonl");
  await mkdir(dirname(file), { recursive: true });
  await appendFile(
    file,
    JSON.stringify({
      requestId,
      jobId,
      status,
      estimatedCost,
      output,
      at: new Date().toISOString(),
    }) + "\n",
    { mode: 0o600 },
  );
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  console.log(
    JSON.stringify({
      usage:
        "Adapt this client module with service-specific subcommands, auth headers and response validation before installing the connector skill.",
    }),
  );
  process.exitCode = process.argv.includes("--help") ? 0 : 64;
}

// The authored client must export a cheap, read-only, authenticated probe.
import { probe } from "./client.mjs";

await probe().then(
  () => console.log(JSON.stringify({ ok: true })),
  (error) => {
    // Provider exceptions can echo credentials: print only the fixed classification.
    const code = [75, 76, 77].includes(error.exitCode) ? error.exitCode : 76;
    console.error(
      JSON.stringify({
        ok: false,
        code,
        message:
          code === 77
            ? "Credential rejected"
            : code === 75
              ? "Try again later"
              : "Verification failed",
      }),
    );
    process.exitCode = code;
  },
);
